  --green-bg:  #edfaf4;
  --green-b:   #9ddfc4;
  --blue:      #1a52a0;
  --blue-bg:   #eef4fd;
  --blue-b:    #a8c5f0;
  --purple:    #5e3a9c;
  --purple-bg: #f5f0fd;
  --purple-b:  #cbafef;

  --nav-h: 60px;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --r-xl: 22px;

  --font-head: 'Playfair Display', Georgia, serif;
  --font-body: 'Plus Jakarta Sans', system-ui, sans-serif;

  --shadow-sm: 0 1px 3px rgba(0,0,0,.06), 0 1px 2px rgba(0,0,0,.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,.08), 0 2px 4px rgba(0,0,0,.04);
  --shadow-lg: 0 8px 24px rgba(0,0,0,.10), 0 3px 6px rgba(0,0,0,.05);
}

html {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  scroll-behavior: smooth;
  scroll-padding-top: calc(var(--nav-h) + 24px);
}

body { background: var(--bg); }

a { color: var(--navy); text-decoration: none; }
a:hover { text-decoration: underline; }

code {
  font-family: 'Fira Mono', ui-monospace, monospace;
  font-size: 0.82em;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 0.1em 0.35em;
  color: var(--text-2);
}

/* ── NAV ─────────────────────────────────────── */
.top-nav {
  position: sticky;
  top: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: var(--nav-h);
  padding: 0 24px;
  background: rgba(247,246,242,0.94);
  border-bottom: 1px solid var(--border);
  backdrop-filter: blur(12px);
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
}
.top-nav::-webkit-scrollbar { display: none; }
.top-nav a, .nav-btn {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  padding: 6px 14px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--surface);
  color: var(--text-2);
  font-size: 0.82rem;
  font-weight: 600;
  white-space: nowrap;
  transition: all 160ms;
}
.top-nav a:hover, .nav-btn:hover {
  border-color: var(--navy2);
  color: var(--navy);
  background: var(--blue-bg);
  text-decoration: none;
}

/* ── PAGE SHELL ──────────────────────────────── */
main, .page-shell {
  width: min(var(--max-w, 1440px), calc(100% - 48px));
  margin: 0 auto;
}

section {
  margin-block: 56px;
}

/* ── SECTION HEADINGS ────────────────────────── */
.section-head {
  margin-bottom: 28px;
}
.section-kicker {
  display: inline-block;
  padding: 3px 12px;
  background: var(--navy);
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  border-radius: 999px;
  margin-bottom: 10px;
}
.section-head h2, h2.section-heading {
  font-family: var(--font-head);
  font-size: clamp(1.5rem, 2.5vw, 2rem);
  font-weight: 700;
  color: var(--navy);
  line-height: 1.2;
  margin-bottom: 8px;
}
.section-head p, .section-subtitle {
  color: var(--text-2);
  font-size: 0.95rem;
}
.section-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
  padding-bottom: 14px;
  border-bottom: 2px solid var(--border);
}
.section-heading h2, .section-heading h3 {
  font-family: var(--font-head);
  color: var(--navy);
  font-size: 1.5rem;
  line-height: 1.2;
}
.section-heading .section-kicker { margin-bottom: 6px; }

/* ── START-HERE CARDS ────────────────────────── */
.start-card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 20px;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 200ms, transform 200ms;
}
.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  border-radius: 12px;
  font-size: 1.4rem;
  margin-bottom: 14px;
}

.card h3, .card h4 { 
  font-family: var(--font-head);
  font-size: 1.1rem;
  color: var(--navy);
  margin-bottom: 10px;
}

.card p, .card li {
  font-size: 0.9rem;
  color: var(--text-2);
  line-height: 1.55;
}
.card ul, .card ol {
  padding-left: 18px;
  margin-bottom: 10px;
}
.card li { margin-bottom: 4px; }

.card a[href^="#"] {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
  padding: 7px 14px;
  border: 1px solid currentColor;
  border-radius: 999px;
  font-size: 0.8rem;
  font-weight: 700;
  text-decoration: none;
}

.card-stat {
  font-family: var(--font-head);
  font-size: 2.5rem;
  font-weight: 700;
  line-height: 1;
  margin-bottom: 8px;
}

.card-must-review {
  border-top: 4px solid var(--red);
  background: linear-gradient(160deg, var(--red-bg) 0%, var(--surface) 60%);
}
.card-must-review .card-stat, .card-must-review h3 { color: var(--red); }
.card-must-review a[href^="#"] { color: var(--red); border-color: var(--red-b); background: var(--red-bg); }

.card-high-marks {
  border-top: 4px solid var(--amber);
  background: linear-gradient(160deg, var(--amber-bg) 0%, var(--surface) 60%);
}
.card-high-marks .card-stat, .card-high-marks h3 { color: var(--amber); }
.card-high-marks a[href^="#"] { color: var(--amber); border-color: var(--amber-b); background: var(--amber-bg); }

.card-rare-dangerous {
  border-top: 4px solid var(--purple);
  background: linear-gradient(160deg, var(--purple-bg) 0%, var(--surface) 60%);
}
.card-rare-dangerous .card-stat, .card-rare-dangerous h3 { color: var(--purple); }
.card-rare-dangerous a[href^="#"] { color: var(--purple); border-color: var(--purple-b); background: var(--purple-bg); }

.card-easy-marks {
  border-top: 4px solid var(--green);
  background: linear-gradient(160deg, var(--green-bg) 0%, var(--surface) 60%);
}
.card-easy-marks .card-stat, .card-easy-marks h3 { color: var(--green); }
.card-easy-marks a[href^="#"] { color: var(--green); border-color: var(--green-b); background: var(--green-bg); }

/* ── PRIORITY MATRIX ─────────────────────────── */
.priority-matrix {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

.matrix-quadrant {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-lg);
  padding: 22px 24px;
  box-shadow: var(--shadow-sm);
}
.matrix-quadrant h3 {
  font-family: var(--font-head);
  font-size: 1.05rem;
  color: var(--navy);
  margin-bottom: 6px;
}
.quadrant-count {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--text-3);
  margin-bottom: 14px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.matrix-core-priorities { border-left: 5px solid var(--red); }
.matrix-core-priorities h3 { color: var(--red); }
.matrix-routine-marks { border-left: 5px solid var(--blue); }
.matrix-routine-marks h3 { color: var(--blue); }
.matrix-rare-dangerous { border-left: 5px solid var(--purple); }
.matrix-rare-dangerous h3 { color: var(--purple); }
.matrix-low-priority { border-left: 5px solid var(--green); }
.matrix-low-priority h3 { color: var(--green); }

.compact-topic-list {
  list-style: none;
  padding: 0;
  max-height: 360px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--border-md) transparent;
}
.compact-topic-list li {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 10px;
  padding: 7px 0;
  border-bottom: 1px solid var(--border);
  font-size: 0.86rem;
}
.compact-topic-list li:last-child { border-bottom: none; }
.topic-name { color: var(--text-2); flex: 1; }
.topic-meta {
  flex: 0 0 auto;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-3);
  white-space: nowrap;
}

/* ── MARKS WARNING ───────────────────────────── */
.marks-warning {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 14px 18px;
  margin-bottom: 22px;
  background: var(--amber-bg);
  border: 1px solid var(--amber-b);
  border-left: 4px solid var(--amber);
  border-radius: var(--r-md);
  font-size: 0.88rem;
  color: var(--text-2);
  line-height: 1.5;
}
.marks-warning strong { color: var(--amber); }
.marks-warning::before { content: "⚠️"; flex: 0 0 auto; }

/* ── CARD SECTION (URGENT) ───────────────────── */
.card-section {
  margin-bottom: 36px;
}
.card-section > h3 {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-head);
  font-size: 1.1rem;
  color: var(--navy);
  margin-bottom: 16px;
  padding-bottom: 10px;
  border-bottom: 2px solid var(--border);
}
.count {
  display: inline-flex;
  align-items: center;
  padding: 2px 10px;
  background: var(--navy);
  color: #fff;
  font-size: 0.72rem;
  font-weight: 700;
  border-radius: 999px;
}

/* ── TOPIC CARDS ─────────────────────────────── */
.topic-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 16px;
}

.topic-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  padding: 18px 20px;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 180ms;
}
.topic-card:hover { box-shadow: var(--shadow-md); }

.topic-card h3 {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 10px;
  line-height: 1.35;
}

.card-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 12px;
}

.student {
  font-size: 0.875rem;
  color: var(--text-2);
  line-height: 1.5;
  padding: 10px 12px;
  background: var(--bg-alt);
  border-radius: var(--r-sm);
  margin-bottom: 10px;
  border-left: 3px solid var(--border-md);
  font-style: italic;
}

.topic-card p {
  font-size: 0.86rem;
  color: var(--text-2);
  line-height: 1.5;
  margin-top: 8px;
}
.topic-card strong { color: var(--text); }

.card-pair {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 4px 12px;
  margin-bottom: 10px;
  font-size: 0.8rem;
}
.card-pair span:nth-child(odd) {
  color: var(--text-3);
  font-weight: 700;
  text-transform: uppercase;
  font-size: 0.7rem;
  letter-spacing: 0.05em;
}
.card-pair span:nth-child(even) { color: var(--text-2); }

/* ── PILLS / BADGES ──────────────────────────── */
.pill, .badge, .cf-badge,
.priority-high, .priority-medium, .priority-low, .priority-review {
  display: inline-flex;
  align-items: center;
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 0.73rem;
  font-weight: 700;
  white-space: nowrap;
  line-height: 1.3;
}

.pill {
  background: var(--bg-alt);
  border: 1px solid var(--border);
  color: var(--text-2);
}

/* Frequency badges */
.badge-never, .badge.never {
  background: var(--red-bg);
  border: 1px solid var(--red-b);
  color: var(--red);
}
.badge-very-rare {
  background: var(--purple-bg);
  border: 1px solid var(--purple-b);
  color: var(--purple);
}
.badge-rare {
  background: var(--amber-bg);
  border: 1px solid var(--amber-b);
  color: var(--amber);
}
.badge-moderate {
  background: var(--blue-bg);
  border: 1px solid var(--blue-b);
  color: var(--blue);
}
.badge-frequent {
  background: var(--green-bg);
  border: 1px solid var(--green-b);
  color: var(--green);
}

/* Difficulty badges */
.badge-easy, .difficulty-easy, .cf-badge.easy {
  background: var(--green-bg);
  border: 1px solid var(--green-b);
  color: var(--green);
}
.badge-medium, .difficulty-medium, .cf-badge.medium {
  background: var(--blue-bg);
  border: 1px solid var(--blue-b);
  color: var(--blue);
}
.badge-hard, .difficulty-hard, .cf-badge.hard {
  background: var(--amber-bg);
  border: 1px solid var(--amber-b);
  color: var(--amber);
}
.badge-very-hard, .difficulty-very-hard, .cf-badge.very-hard {
  background: var(--red-bg);
  border: 1px solid var(--red-b);
  color: var(--red);
}
.difficulty-na, .cf-badge.na {
  background: var(--bg-alt);
  border: 1px solid var(--border);
  color: var(--text-3);
}

/* Confidence badges */
.cf-badge.high { background: var(--green-bg); border: 1px solid var(--green-b); color: var(--green); }
.cf-badge.medium { background: var(--amber-bg); border: 1px solid var(--amber-b); color: var(--amber); }
.cf-badge.low { background: var(--red-bg); border: 1px solid var(--red-b); color: var(--red); }

.cf-badge {
  background: var(--bg-alt);
  border: 1px solid var(--border);
  color: var(--text-2);
}

/* Priority badges */
.priority-high { background: var(--red-bg); border: 1px solid var(--red-b); color: var(--red); }
.priority-medium { background: var(--amber-bg); border: 1px solid var(--amber-b); color: var(--amber); }
.priority-low { background: var(--green-bg); border: 1px solid var(--green-b); color: var(--green); }
.priority-review { background: var(--purple-bg); border: 1px solid var(--purple-b); color: var(--purple); }

/* ── REVISION TABLE ───────────────────────────── */
.revision-table-wrap, .table-wrap, .cf-table-wrap {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-lg);
  overflow: auto;
  box-shadow: var(--shadow-sm);
}

.revision-table, table, .cf-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
  min-width: 800px;
}

th {
  padding: 12px 16px;
  background: var(--navy);
  color: #fff;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  text-align: left;
  position: sticky;
  top: var(--nav-h);
  z-index: 50;
  border-bottom: 2px solid var(--navy2);
}

td {
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
  color: var(--text-2);
  vertical-align: top;
  text-align: left;
  line-height: 1.45;
}

tbody tr:last-child td { border-bottom: none; }
tbody tr:hover td { background: var(--blue-bg); }
tbody tr:nth-child(even) td { background: var(--bg); }
tbody tr:nth-child(even):hover td { background: var(--blue-bg); }

td strong {
  display: block;
  color: var(--text);
  font-weight: 700;
  margin-bottom: 2px;
}
td span:not(.badge):not(.difficulty):not(.cf-badge):not(.priority-high):not(.priority-medium):not(.priority-low):not(.priority-review) {
  display: block;
  font-size: 0.8rem;
  color: var(--text-3);
  margin-top: 2px;
}

.num, .cf-num { font-variant-numeric: tabular-nums; font-weight: 700; color: var(--text); }
.skill { color: var(--text-2); }
.method { font-size: 0.84rem; color: var(--text-2); }

/* ── REVISION CARDS (EASY MARKS) ──────────────── */
.revision-priority-sections { margin-top: 0; }
.revision-card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(270px, 1fr));
  gap: 16px;
}

.revision-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  padding: 18px 20px;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 180ms;
}
.revision-card:hover { box-shadow: var(--shadow-md); }

.revision-card__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border);
}
.revision-card h3 {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--navy);
  line-height: 1.3;
}
.revision-card__header span {
  flex: 0 0 auto;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--text-3);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  text-align: right;
  max-width: 42%;
}

.revision-card__stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-bottom: 12px;
}
.revision-card__stats > div {
  background: var(--bg-alt);
  border: 1px solid var(--border);
  border-radius: var(--r-sm);
  padding: 8px 10px;
}
.revision-card__stats dt {
  font-size: 0.68rem;
  font-weight: 700;
  color: var(--text-3);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 2px;
}
.revision-card__stats dd {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--navy);
  font-variant-numeric: tabular-nums;
}

.revision-card p {
  font-size: 0.85rem;
  color: var(--text-2);
  line-height: 1.5;
  margin-top: 6px;
}

/* ── TRAP CARDS ───────────────────────────────── */
.trap-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 18px;
}

.trap-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-left: 5px solid var(--red);
  border-radius: var(--r-md);
  padding: 18px 20px;
  box-shadow: var(--shadow-sm);
}
.trap-card h3 {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--red);
  margin-bottom: 6px;
  line-height: 1.3;
}
.trap-name {
  font-size: 0.7rem;
  color: var(--text-3);
  font-family: 'Fira Mono', ui-monospace, monospace;
  margin-bottom: 10px;
  padding: 3px 8px;
  background: var(--bg-alt);
  border-radius: 4px;
  display: inline-block;
}
.trap-card p { font-size: 0.86rem; color: var(--text-2); line-height: 1.5; margin-top: 8px; }
.trap-card strong { color: var(--text); }

/* ── CHAPTER EXPLORER (DETAILS/ACCORDIONS) ────── */
#chapter-explorer { margin-block: 56px; }
.cf-section-head {
  margin-bottom: 24px;
}
.cf-section-head h2 {
  font-family: var(--font-head);
  font-size: clamp(1.4rem, 2vw, 1.9rem);
  color: var(--navy);
  margin-bottom: 6px;
}
.cf-section-head p { color: var(--text-2); font-size: 0.93rem; }

details {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  margin-bottom: 10px;
  transition: box-shadow 180ms;
}
details:hover { box-shadow: var(--shadow-md); }
details[open] { box-shadow: var(--shadow-md); }

summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 20px;
  cursor: pointer;
  list-style: none;
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--navy);
  background: var(--surface);
  user-select: none;
  transition: background 150ms;
}
summary::-webkit-details-marker { display: none; }
summary:hover { background: var(--blue-bg); }
details[open] summary {
  border-bottom: 1px solid var(--border);
  background: var(--bg-alt);
}
summary::after {
  content: "+";
  font-size: 1.2rem;
  color: var(--text-3);
  font-weight: 300;
  flex: 0 0 auto;
}
details[open] summary::after { content: "−"; }

.cf-summary-meta {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-3);
}

.cf-chapter-body, .details-body {
  padding: 20px;
}

.cf-coverage {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 16px;
}

.cf-chapter-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 16px;
}

.cf-chapter-grid article {
  background: var(--bg-alt);
  border: 1px solid var(--border);
  border-radius: var(--r-sm);
  padding: 14px 16px;
}
.cf-chapter-grid article h3 {
  font-size: 0.85rem;
  font-weight: 800;
  color: var(--navy);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 10px;
