/* ── REVISION TABLE ───────────────────────────── */
.revision-table-wrap, .table-wrap, .cf-table-wrap {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-lg);
  overflow: auto;
  box-shadow: var(--shadow-sm);
}

.revision-table, table, .cf-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
  min-width: 800px;
}

th {
  padding: 12px 16px;
  background: var(--navy);
  color: #fff;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  text-align: left;
  position: sticky;
  top: var(--nav-h);
  z-index: 50;
  border-bottom: 2px solid var(--navy2);
}

td {
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
  color: var(--text-2);
  vertical-align: top;
  text-align: left;
  line-height: 1.45;
}

tbody tr:last-child td { border-bottom: none; }
tbody tr:hover td { background: var(--blue-bg); }
tbody tr:nth-child(even) td { background: var(--bg); }
tbody tr:nth-child(even):hover td { background: var(--blue-bg); }

td strong {
  display: block;
  color: var(--text);
  font-weight: 700;
  margin-bottom: 2px;
}
td span:not(.badge):not(.difficulty):not(.cf-badge):not(.priority-high):not(.priority-medium):not(.priority-low):not(.priority-review) {
  display: block;
  font-size: 0.8rem;
  color: var(--text-3);
  margin-top: 2px;
}

.num, .cf-num { font-variant-numeric: tabular-nums; font-weight: 700; color: var(--text); }
.skill { color: var(--text-2); }
.method { font-size: 0.84rem; color: var(--text-2); }

/* ── REVISION CARDS (EASY MARKS) ──────────────── */
.revision-priority-sections { margin-top: 0; }
.revision-card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(270px, 1fr));
  gap: 16px;
}

.revision-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  padding: 18px 20px;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 180ms;
}
.revision-card:hover { box-shadow: var(--shadow-md); }

.revision-card__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border);
}
.revision-card h3 {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--navy);
  line-height: 1.3;
}
.revision-card__header span {
  flex: 0 0 auto;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--text-3);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  text-align: right;
  max-width: 42%;
}

.revision-card__stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-bottom: 12px;
}
.revision-card__stats > div {
  background: var(--bg-alt);
  border: 1px solid var(--border);
  border-radius: var(--r-sm);
  padding: 8px 10px;
}
.revision-card__stats dt {
  font-size: 0.68rem;
  font-weight: 700;
  color: var(--text-3);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 2px;
}
.revision-card__stats dd {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--navy);
  font-variant-numeric: tabular-nums;
}

.revision-card p {
  font-size: 0.85rem;
  color: var(--text-2);
  line-height: 1.5;
  margin-top: 6px;
}

/* ── TRAP CARDS ───────────────────────────────── */
.trap-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 18px;
}

.trap-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-left: 5px solid var(--red);
  border-radius: var(--r-md);
  padding: 18px 20px;
  box-shadow: var(--shadow-sm);
}
.trap-card h3 {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--red);
  margin-bottom: 6px;
  line-height: 1.3;
}
.trap-name {
  font-size: 0.7rem;
  color: var(--text-3);
  font-family: 'Fira Mono', ui-monospace, monospace;
  margin-bottom: 10px;
  padding: 3px 8px;
  background: var(--bg-alt);
  border-radius: 4px;
  display: inline-block;
}
.trap-card p { font-size: 0.86rem; color: var(--text-2); line-height: 1.5; margin-top: 8px; }
.trap-card strong { color: var(--text); }

/* ── CHAPTER EXPLORER (DETAILS/ACCORDIONS) ────── */
#chapter-explorer { margin-block: 56px; }
.cf-section-head {
  margin-bottom: 24px;
}
.cf-section-head h2 {
  font-family: var(--font-head);
  font-size: clamp(1.4rem, 2vw, 1.9rem);
  color: var(--navy);
  margin-bottom: 6px;
}
.cf-section-head p { color: var(--text-2); font-size: 0.93rem; }

details {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  margin-bottom: 10px;
  transition: box-shadow 180ms;
}
details:hover { box-shadow: var(--shadow-md); }
details[open] { box-shadow: var(--shadow-md); }

summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 20px;
  cursor: pointer;
  list-style: none;
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--navy);
  background: var(--surface);
  user-select: none;
  transition: background 150ms;
}
summary::-webkit-details-marker { display: none; }
summary:hover { background: var(--blue-bg); }
details[open] summary {
  border-bottom: 1px solid var(--border);
  background: var(--bg-alt);
}
summary::after {
  content: "+";
  font-size: 1.2rem;
  color: var(--text-3);
  font-weight: 300;
  flex: 0 0 auto;
}
details[open] summary::after { content: "−"; }

.cf-summary-meta {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-3);
}

.cf-chapter-body, .details-body {
  padding: 20px;
}

.cf-coverage {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 16px;
}

.cf-chapter-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 16px;
}

.cf-chapter-grid article {
  background: var(--bg-alt);
  border: 1px solid var(--border);
  border-radius: var(--r-sm);
  padding: 14px 16px;
}
.cf-chapter-grid article h3 {
  font-size: 0.85rem;
  font-weight: 800;
  color: var(--navy);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 10px;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--border-md);
}
.cf-chapter-grid article ul {
  list-style: none;
  padding: 0;
}
.cf-chapter-grid article li {
  font-size: 0.83rem;
  color: var(--text-2);
  padding: 5px 0;
  border-bottom: 1px solid var(--border);
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 5px;
}
.cf-chapter-grid article li:last-child { border-bottom: none; }
.cf-chapter-grid article li strong { color: var(--text); display: inline; }

.cf-scroll-list {
  max-height: 200px;
  overflow-y: auto;
  scrollbar-width: thin;
}
.cf-scroll-list ul { list-style: none; padding: 0; }
.cf-scroll-list li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  padding: 5px 0;
  border-bottom: 1px dotted var(--border);
  font-size: 0.82rem;
}
.cf-scroll-list li:last-child { border-bottom: none; }

.cf-code, .mono code {
  font-family: 'Fira Mono', ui-monospace, monospace;
  font-size: 0.8em;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 1px 5px;
  color: var(--text-2);
}

.cf-muted { color: var(--text-3); font-size: 0.82rem; }

/* ── QUESTION FINDER ─────────────────────────── */
#question-finder { margin-block: 56px; }

.cf-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 12px;
  margin-bottom: 14px;
  padding: 18px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
}

.cf-controls label {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--text-3);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.cf-controls label.cf-search { flex: 1; min-width: 200px; }

input[type="search"], input[type="text"], input[type="number"], select {
  min-height: 38px;
  padding: 7px 12px;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  border-radius: var(--r-sm);
  color: var(--text);
  font: inherit;
  font-size: 0.9rem;
  transition: border-color 150ms, box-shadow 150ms;
}
input[type="search"]:focus, input[type="text"]:focus, select:focus {
  border-color: var(--navy);
  box-shadow: 0 0 0 3px rgba(27,45,82,0.12);
  outline: none;
}
input::placeholder { color: var(--text-3); }

.cf-presets {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 16px;
}

button, .cf-presets button {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 7px 16px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 999px;
  color: var(--text-2);
  font: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 150ms;
}
button:hover, .cf-presets button:hover {
  background: var(--blue-bg);
  border-color: var(--navy2);
  color: var(--navy);
}

.cf-count {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text-3);
  margin-bottom: 10px;
}

/* ── LOW CONFIDENCE TABLE ────────────────────── */
table[style*="min-width: 1700px"] {
  min-width: 1200px;
}

/* ── FOOTER ───────────────────────────────────── */
.footer {
  padding: 16px 0 40px;
  text-align: center;
  font-size: 0.82rem;
  color: var(--text-3);
  border-top: 1px solid var(--border);
  margin-top: 40px;
}

/* ── RESPONSIVE ───────────────────────────────── */
@media (max-width: 900px) {
  main, .page-shell { width: calc(100% - 32px); }
  .priority-matrix { grid-template-columns: 1fr; }
  .cf-chapter-grid { grid-template-columns: 1fr; }
}
@media (max-width: 640px) {
  main, .page-shell { width: calc(100% - 20px); }
  .start-card-grid, .topic-grid, .trap-grid, .revision-card-grid { grid-template-columns: 1fr; }
  .top-nav { padding: 0 12px; }
  section { margin-block: 36px; }
}

@media print {
  .top-nav { display: none !important; }
  body, html { background: #fff !important; }
  section { break-inside: avoid; }
  .card, .topic-card, .trap-card, table { box-shadow: none !important; }
  .compact-topic-list { max-height: none !important; overflow: visible !important; }
  .cf-scroll-list { max-height: none !important; overflow: visible !important; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; }
}

/* ── MISC UTILS ───────────────────────────────── */
.muted { color: var(--text-3); }
.mono { font-family: 'Fira Mono', ui-monospace, monospace; }
"""

